import {telemetryFor,telemetryLabel} from './runtime-client.js';
import {ROLES,RELATION_TYPES,MEMORIES,ISOLATIONS,SKILLS,registryStats,filterAgents} from './agents.js';
import {BASE_SKILL} from './domain.js';
export const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const esc=escapeHtml;
const options=(items,selected)=>Object.entries(items).map(([value,label])=>`<option value="${esc(value)}" ${value===selected?'selected':''}>${esc(label)}</option>`).join('');
const chips=items=>items.length?items.map(v=>`<span class="agent-chip">${esc(v)}</span>`).join(''):'<span class="muted">未配置</span>';
const metric=(title,value,caption)=>`<article class="metric"><div>${title}</div><strong>${value}</strong><small>${caption}</small></article>`;
const agentButton=(agent)=>`<button class="text-button" data-agent-select="${esc(agent.id)}">${esc(agent.name)}</button>`;

export function topology(registry,selectedId,runtime=null){
  const defaults=[[360,58],[360,200],[130,355],[590,355],[360,515]];
  const nodes=registry.agents.map((a,i)=>({...a,x:registry.agents.length<=5?defaults[i][0]:130+(i%3)*230,y:registry.agents.length<=5?defaults[i][1]:58+Math.floor(i/3)*160}));
  const positions=new Map(nodes.map(a=>[a.id,a]));
  const height=Math.max(210,...nodes.map(a=>a.y+72));
  const colors={task:'#6264d9',evidence:'#378d82',feedback:'#b27b39',review:'#8390a5'};
  const edges=registry.relationships.map(r=>{
    const a=positions.get(r.from),b=positions.get(r.to),dx=b.x-a.x,dy=b.y-a.y;
    const vertical=Math.abs(dy)>Math.abs(dx)*0.5;
    const sx=a.x+(vertical?0:Math.sign(dx)*91),sy=a.y+(vertical?Math.sign(dy)*43:0);
    const tx=b.x-(vertical?0:Math.sign(dx)*91),ty=b.y-(vertical?Math.sign(dy)*43:0);
    const bend=r.type==='review'&&Math.abs(dy)>300?210:0;
    const d=vertical?`M ${sx} ${sy} C ${sx+bend} ${(sy+ty)/2}, ${tx+bend} ${(sy+ty)/2}, ${tx} ${ty}`:`M ${sx} ${sy} C ${(sx+tx)/2} ${sy+36}, ${(sx+tx)/2} ${ty+36}, ${tx} ${ty}`;
    return `<path d="${d}" fill="none" stroke="${colors[r.type]}" stroke-width="2" ${r.type==='feedback'?'stroke-dasharray="6 4"':''} opacity="${selectedId&&r.from!==selectedId&&r.to!==selectedId?'.18':'.85'}" marker-end="url(#arrow-${r.type})"/>`;
  }).join('');
  return `<div class="topology-scroll" tabindex="0" aria-label="代理人工作關係圖，可水平捲動"><div class="topology-canvas" style="height:${height}px"><svg viewBox="0 0 720 ${height}" aria-hidden="true"><defs>${Object.entries(colors).map(([type,color])=>`<marker id="arrow-${type}" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8" fill="${color}"/></marker>`).join('')}</defs>${edges}</svg>${nodes.map(a=>`<button data-agent-node class="graph-node live-node-${runtime?.error?'stale':telemetryFor(runtime,a.id)?.status||'idle'} ${a.id===selectedId?'selected':''} ${a.enabled?'':'disabled-agent'}" style="left:${a.x-90}px;top:${a.y-43}px" data-agent-select="${esc(a.id)}" aria-pressed="${a.id===selectedId}"><span class="graph-node-id">${esc(a.id)} · ${a.enabled?'設定啟用':'設定停用'}</span><strong>${esc(a.name)}</strong><small>${ROLES[a.role]} · ${runtime?.data?.latestRun?telemetryLabel(runtime,a.id):"未連線"}</small></button>`).join('')}</div></div>`;
}

function detail(state,a,pickedSkill,runtime){
  if(!a)return '<section class="card agent-detail"><div class="empty">選取或新增代理人，查看角色、屬性與 Skill。</div></section>';
  const skills=SKILLS.filter(s=>a.skillIds.includes(s.id)),skill=skills.find(s=>s.id===pickedSkill)||skills[0];
  const telemetry=telemetryFor(runtime,a.id);
  const frozen=telemetry&&runtime?.data?.latestRun?.task==='llm-evolution'?runtime.data.latestRun.llmConfig:null;
  const active=state.releases.find(r=>r.id===state.activeReleaseId);
  const body=skill?.id==='python-fix-and-verify'?(active?.body||BASE_SKILL):skill?.body;
  const properties=[['Runtime',a.runtime],['模型',a.model],['記憶方式',MEMORIES[a.memory]],['隔離方式',ISOLATIONS[a.isolation]],['步數上限',a.maxSteps],['Temperature',a.temperature],['框架連線','未連線'],['本次工作狀態',telemetryLabel(runtime,a.id)],['工作 PID',telemetry?.pid??'—'],['工作角色',telemetry?ROLES[telemetry.role]||telemetry.role:'—'],['配置狀態',a.enabled?'設定啟用':'設定停用']];
  if(frozen)properties.push(['本次執行 adapter',telemetry.adapter||'ollama-skill-role'],['實驗凍結模型',frozen.provider.config.model],['基準 Skill 版本',frozen.baseline.label+' · '+frozen.baseline.skill.name],['本次模型 Temperature',0],['任務記憶','每題使用全新 messages，無工具執行權限']);
  const peers=new Map(state.registry.agents.map(v=>[v.id,v]));
  const related=state.registry.relationships.filter(r=>r.from===a.id||r.to===a.id);
  return `<section class="card agent-detail" aria-labelledby="agent-detail-title"><div class="card-heading"><div><p class="eyebrow">AGENT DETAILS · ${esc(a.id)}</p><h2 id="agent-detail-title">${esc(a.name)}</h2><p>${ROLES[a.role]} · 設定角色，尚未啟動 Runtime</p></div><button class="button secondary" data-agent-edit="${esc(a.id)}">編輯設定</button></div><dl class="agent-properties">${properties.map(([k,v])=>`<dt>${k}</dt><dd>${esc(v)}</dd>`).join('')}</dl><div class="agent-section"><h3>工具配置 <span class="count">${a.tools.length}</span></h3><div class="agent-chips">${chips(a.tools)}</div><p class="agent-caption">工具名稱僅為設定，不授予執行權限。</p></div><div class="agent-section"><h3>Skills <span class="count">${skills.length}</span></h3><div class="skill-picker">${skills.map(s=>`<button data-agent-skill="${s.id}" class="skill-choice ${s.id===skill?.id?'selected':''}" aria-pressed="${s.id===skill?.id}"><strong>${s.name}</strong><code>${s.id}</code><small>${s.evolvable?'本輪演化目標':'固定輔助技能'}</small></button>`).join('')||'<p class="muted">尚未配置 Skill。</p>'}</div>${skill?`<div class="skill-summary"><span class="soft-tag">${skill.id==='python-fix-and-verify'?(active?'候選展示版本':'S0 · baseline'):skill.version}</span><p>${esc(skill.description)}</p><code>${esc(skill.id)}/SKILL.md · 邏輯路徑</code></div><pre class="agent-skill-body">${esc(body)}</pre>${skill.evolvable?'<button class="button secondary" data-action="go-evolution">檢閱技能演化 →</button>':''}`:''}</div><div class="agent-section"><h3>工作關係 <span class="count">${related.length}</span></h3><ul class="agent-peer-list">${related.map(r=>`<li><span class="relation-tag ${r.type}">${r.from===a.id?'交付 →':'接收 ←'} ${RELATION_TYPES[r.type]}</span>${agentButton(peers.get(r.from===a.id?r.to:r.from))}<small>${esc(r.artifact)}</small></li>`).join('')||'<li class="muted">尚無工作關係。</li>'}</ul></div><div class="card-actions"><button class="button danger" data-agent-delete="${esc(a.id)}">刪除代理人設定</button></div></section>`;
}

export function agentsView(state,{selectedId=null,query='',role='all',pickedSkill=null,runtime=null}={}){
  const {registry}=state,stats=registryStats(registry),agents=filterAgents(registry,{query,role});
  const selected=registry.agents.find(a=>a.id===selectedId)||agents[0]||registry.agents[0];
  const map=new Map(registry.agents.map(a=>[a.id,a]));
  return `<div class="page-heading"><div><p class="eyebrow">AGENT WORKSPACE · PHASE 02</p><h1>代理人與工作關係</h1><p>查看角色分工、執行設定與 Skill，檢閱任務和證據如何流動。</p></div><div class="actions"><button class="button secondary" data-action="export">↓ 匯出工作區</button><button class="button primary" data-agent-new>＋ 新增代理人</button></div></div><div class="demo-banner"><span class="info-icon">i</span><div><strong>代理人配置 · 展示模式</strong><span>設定與關係保留於此瀏覽器；目前沒有連線的 Runtime，關係圖不代表實際執行紀錄。</span></div></div><section class="card team-summary"><div><h2>實際執行狀態 · polling 更新</h2><p>${runtime?.lastSuccess?`最近成功更新：${new Date(runtime.lastSuccess).toLocaleTimeString('zh-TW')} · ${runtime.error?'快照過期':'本機服務已連線'}`:'目前沒有可用的本機服務快照'}</p></div><button class="button secondary" data-page="runtime">開啟執行監控 →</button></section><div class="metrics">${metric('已設定代理人',stats.total,`${stats.enabled} 個設定啟用 · 尚未執行`)}${metric('實際連線',stats.connected,'Runtime 尚未接入')}${metric('已配置 Skills',stats.skills,'不同 Skill ID，不重複計算')}${metric('工作關係',stats.relationships,'有方向的任務與證據交付')}</div><div class="agent-workspace"><div class="agent-main"><section class="card"><div class="card-heading"><div><h2>代理人清單</h2><p>搜尋名稱、Runtime、角色、工具或 Skill ID。</p></div><span class="count">${agents.length} / ${stats.total}</span></div><div class="agent-filters"><label>搜尋代理人<input type="search" data-agent-search value="${esc(query)}" placeholder="名稱、角色或 Skill…" maxlength="100"></label><label>角色<select data-agent-role><option value="all">全部角色</option>${options(ROLES,role)}</select></label></div><div class="agent-list">${agents.map(a=>`<button class="agent-row ${a.id===selected?.id?'selected':''}" data-agent-select="${esc(a.id)}" aria-pressed="${a.id===selected?.id}"><span class="agent-symbol">${{coordinator:'C',worker:'W',reflector:'R',evaluator:'E',reviewer:'V'}[a.role]}</span><span class="agent-row-copy"><strong>${esc(a.name)}</strong><small>${ROLES[a.role]} · ${esc(a.runtime)}</small><span>${esc(a.id)} · ${a.skillIds.length} Skills · ${a.enabled?'設定啟用':'設定停用'}</span></span><span class="live-status ${runtime?.error?'stale':telemetryFor(runtime,a.id)?.status||'idle'}">${runtime?.data?.latestRun?telemetryLabel(runtime,a.id):'未連線'}</span></button>`).join('')||'<div class="empty">沒有符合條件的代理人。</div>'}</div></section><section class="card spaced"><div class="card-heading"><div><h2>工作關係圖</h2><p>顯示全部配置。箭頭由交付者指向接收者；點選節點查看詳細資料。</p></div><button class="button secondary" data-relation-new ${stats.total<2?'disabled':''}>＋ 新增關係</button></div><div class="relation-legend">${Object.entries(RELATION_TYPES).map(([type,label])=>`<span class="relation-tag ${type}"><i></i>${label}</span>`).join('')}</div>${stats.total?topology(registry,selected?.id,runtime):'<div class="empty">新增代理人後即可建立工作關係。</div>'}<div class="small-notice">箭頭代表配置的關係；節點狀態來自最近一次實際工作。固定流程不採用自訂關係排程。LLM 實驗依序執行 Coordinator、Worker、Reflector、Evaluator、Reviewer；GEPA adapter 尚未接入。</div></section></div>${detail(state,selected,pickedSkill,runtime)}</div><section class="card spaced"><div class="card-heading"><div><h2>關係與交付內容</h2><p>角色配置改動不會改變目前固定的演化展示流程。</p></div></div><div class="table-wrap"><table class="relationship-table"><thead><tr><th>交付者 → 接收者</th><th>關係</th><th>交付內容</th><th>操作</th></tr></thead><tbody>${registry.relationships.map(r=>`<tr><td>${agentButton(map.get(r.from))}<span class="relation-arrow">→</span>${agentButton(map.get(r.to))}</td><td><span class="relation-tag ${r.type}">${RELATION_TYPES[r.type]}</span></td><td class="artifact-cell">${esc(r.artifact)}</td><td><button class="text-button danger" data-relation-delete="${esc(r.id)}">刪除</button></td></tr>`).join('')||'<tr><td colspan="4">尚無工作關係。</td></tr>'}</tbody></table></div></section>`;
}

export function agentForm(agent){
  const a=agent||{name:'',role:'worker',runtime:'nanobot（規劃）',model:'未設定',memory:'snapshot',isolation:'workspace',maxSteps:20,temperature:0.2,enabled:true,skillIds:[],tools:[]};
  return `<form id="agent-form"><div class="dialog-title"><div><p class="eyebrow">AGENT CONFIGURATION</p><h2>${agent?'編輯':'新增'}代理人設定</h2></div><button type="button" class="icon-button" data-close aria-label="關閉">×</button></div><p class="muted">設定保留於此瀏覽器，尚未連接 Runtime。請只填模型名稱，不要填 API 金鑰。</p><label>名稱<input name="name" required maxlength="80" value="${esc(a.name)}"></label><div class="two-col"><label>角色<select name="role">${options(ROLES,a.role)}</select></label><label>Runtime<input name="runtime" required maxlength="100" value="${esc(a.runtime)}"></label></div><label>模型名稱<input name="model" required maxlength="100" value="${esc(a.model)}"></label><div class="two-col"><label>記憶方式<select name="memory">${options(MEMORIES,a.memory)}</select></label><label>隔離方式<select name="isolation">${options(ISOLATIONS,a.isolation)}</select></label></div><div class="two-col"><label>步數上限<input name="maxSteps" type="number" min="1" max="100" step="1" required value="${a.maxSteps}"></label><label>Temperature<input name="temperature" type="number" min="0" max="2" step="0.01" required value="${a.temperature}"></label></div><label>工具名稱（以逗號分隔）<input name="tools" maxlength="1600" value="${esc(a.tools.join(', '))}" placeholder="read-file, run-tests"></label><fieldset class="skill-fieldset"><legend>配置 Skills</legend>${SKILLS.map(s=>`<label class="check-label"><input type="checkbox" name="skills" value="${s.id}" ${a.skillIds.includes(s.id)?'checked':''}><span>${s.name}<small>${s.id}</small></span></label>`).join('')}</fieldset><label class="check-label"><input type="checkbox" name="enabled" ${a.enabled?'checked':''}>設定啟用（不會啟動代理人）</label><p class="form-error" role="alert"></p><div class="dialog-actions"><button type="button" data-close class="button secondary">取消</button><button type="submit" class="button primary">儲存設定</button></div></form>`;
}
export function relationshipForm(registry){
  const agents=Object.fromEntries(registry.agents.map(a=>[a.id,a.name]));
  return `<form id="relationship-form"><div class="dialog-title"><div><p class="eyebrow">WORK RELATIONSHIP</p><h2>新增工作關係</h2></div><button type="button" class="icon-button" data-close aria-label="關閉">×</button></div><p class="muted">定義角色之間的交付方向與內容。</p><label>交付者<select name="from">${options(agents,registry.agents[0]?.id)}</select></label><label>接收者<select name="to">${options(agents,registry.agents[1]?.id)}</select></label><label>關係類型<select name="type">${options(RELATION_TYPES,'task')}</select></label><label>交付內容<input name="artifact" maxlength="200" required placeholder="任務、技能版本、測試證據…"></label><p class="form-error" role="alert"></p><div class="dialog-actions"><button type="button" data-close class="button secondary">取消</button><button type="submit" class="button primary">建立關係</button></div></form>`;
}
